internal class BohrisShortCodeDecoder : IKuerzelDecoder
    {
        // Mapping from a decoder domain to its corresponding key‑value lookup table.
        readonly Dictionary<DecoderDomain, KVTable> m_decoders;

        /// <summary>
        /// Initializes a new instance of <see cref="BohrisShortCodeDecoder"/>.
        /// </summary>
        /// <param name="bovis_db">Connection to the main Bovis database.</param>
        /// <param name="config_db">Connection to the configuration database.</param>
        internal BohrisShortCodeDecoder(IDbConnection bovis_db, IDbConnection config_db)
        {
            m_decoders = new Dictionary<DecoderDomain, KVTable>{
                {BohrisDecoderDomains.DomFarbe,new KVTable(bovis_db,"SELECT FARBE as key_, BEDEUTUNG as value_ FROM L_FARBE")},
                {BohrisDecoderDomains.DomGenese,new KVTable(bovis_db,"SELECT GENESE as key_, BEDEUTUNG as value_ FROM L_GENESE")},
                {BohrisDecoderDomains.DomHydro,new KVTable(config_db,"SELECT id AS key_, bovis AS value_ FROM bue_key_hydrostrat")},
                {BohrisDecoderDomains.DomPetro,new KVTable(bovis_db,"SELECT PETH as key_, BEDEUTUNG as value_ FROM L_PETH")},
                {BohrisDecoderDomains.DomStrat,new KVTable(bovis_db,"SELECT STRATIGRAPHIE as key_, BEDEUTUNG as value_ FROM L_STRATIGRAPHIE")},
                {BohrisDecoderDomains.DomZusatz,new KVTable(bovis_db,"SELECT ZUSATZ as key_, BEDEUTUNG as value_ FROM L_ZUSATZ")},
                {BohrisDecoderDomains.DomStaPri,new KVTable(bovis_db,"SELECT DS_STA_PRI as key_, BEDEUTUNG as value_ FROM L_DS_STA_PRI")},
            };
        }

