        /// <summary>
        /// Asynchronous counterpart of <see cref="Open"/>. Currently performs the
        /// synchronous open operation and returns a completed task.
        /// </summary>
        public async Task OpenAsync()
        {
            Open();
            await Task.CompletedTask; // to comply with the async signature.
        }

        /// <summary>
        /// Releases unmanaged resources and optionally disposes managed resources.
        /// </summary>
        /// <param name="disposing">
        /// <c>true</c> to release both managed and unmanaged resources; <c>false</c> to release only unmanaged resources.
        /// </param>
        protected virtual void Dispose(bool disposing)
        {
            if (!m_disposedValue)
            {
                if (disposing)
                {
                    // Dispose the underlying DB connection.
                    m_conn.Dispose();
                }
                m_disposedValue = true;
            }
        }

        /// <summary>
        /// Retrieves borehole (Bohrung) information for the specified identifier.
        /// </summary>
        /// <param name="id">The primary key of the borehole record.</param>
        /// <param name="whereClause">Optional additional SQL filter clause.</param>
        /// <returns>A task that resolves to an <see cref="IBovisStammInfo"/> instance.</returns>
        public async Task<IBovisStammInfo> FindBohrungAsync(DbKeyValue id, string whereClause = "")
        {
            return await BohrisStammInfo.Find(this, m_decoder!, m_conn, id, whereClause);
        }

